// Les infos de la boutique arrivent directement dans le trigger.
const data = $('When Executed by Another Workflow').first().json;

return [{
  json: {
    boutiqueId: String(data.boutique_id || ''),
    whatsapp_marchand: String(data.whatsapp_marchand || ''),
    nom_boutique: String(data.nom_boutique || ''),
  }
}];

const data = $('When Executed by Another Workflow').first().json;
const menuRows = $('Lire Menu').all().map(i => i.json);

// Stocks en temps reel depuis Supabase (le dashboard est la source de verite)
let stocks = [];
try {
  stocks = $('Lire stocks').first().json.stock || [];
} catch (e) { stocks = []; }

const parNom = {};
for (const s of stocks) {
  parNom[String(s.nom || '').trim().toLowerCase()] = s;
}

// Selection du jour, avec marquage EPUISE en direct.
const lignes = [];
for (const r of menuRows) {
  // Lire Menu emet un item vide quand l'onglet du marchand n'a aucune ligne.
  if (!r || !r.nom) continue;
  // Le catalogue vient desormais de l application, qui rend `duJour` en
  // booleen ; la feuille rendait `menu_du_jour` en texte. On accepte les deux
  // le temps que plus rien ne vienne de la feuille.
  const duJour = r.duJour === true || String(r.menu_du_jour || '').toUpperCase() === 'TRUE';
  if (!duJour) continue;

  // « Lire stocks » reste l autorite ; a defaut, le catalogue porte lui-meme le
  // stock. NULL veut dire « le marchand ne compte pas ce produit », jamais zero.
  const s = parNom[String(r.nom || '').trim().toLowerCase()];
  const dispo = s ? s.disponible : r.disponible;
  const reste = s ? s.stock : (r.stock === undefined ? null : r.stock);
  const epuise = dispo === false || (reste !== null && reste !== undefined && reste <= 0);
  lignes.push(`- ${r.nom} : ${r.prix} FCFA${epuise ? ' — ⛔ ÉPUISÉ' : ''}`);
}

// « MENU DU JOUR » EST UN CONCEPT DE RESTAURANT.
//
// Une boutique de vetements, une pharmacie ou un quincaillier n ont pas de
// selection quotidienne : ils ont un catalogue. Filtrer sur `duJour` leur
// rendait une carte VIDE, et l assistante annoncait « rien publie aujourd hui »
// alors que les articles etaient bel et bien en ligne sur la vitrine.
//
// Regle : si le marchand n a rien mis en avant, on presente tout ce qui est
// disponible. Celui qui compose une selection la voit respectee ; celui qui
// n en compose pas vend quand meme.
if (lignes.length === 0) {
  for (const r of menuRows) {
    if (!r || !r.nom) continue;
    const s = parNom[String(r.nom || '').trim().toLowerCase()];
    const dispo = s ? s.disponible : r.disponible;
    const reste = s ? s.stock : (r.stock === undefined ? null : r.stock);
    if (dispo === false) continue;
    const epuise = reste !== null && reste !== undefined && reste <= 0;
    lignes.push(`- ${r.nom} : ${r.prix} FCFA${epuise ? ' — ⛔ ÉPUISÉ' : ''}`);
  }
}

// Plafond de commandes du marchand. Le compteur vit dans l'application ; ici
// on ne fait qu'en tirer une consigne pour l'assistante.
//
// Toute lecture douteuse laisse passer : le noeud tolere l'erreur et peut donc
// transmettre autre chose qu'une reponse. On ne bloque que sur un `autorise`
// explicitement faux, jamais sur une absence.
let quota = null;
try { quota = $('Quota commandes').first().json; } catch (e) { quota = null; }
const priseSuspendue = !!quota && quota.autorise === false;

// Le client n'a pas a savoir que son commercant a atteint un plafond : ce
// n'est ni son probleme ni son affaire. On lui donne une porte de sortie
// utile, pas une explication commerciale.
const prise_commande_text = priseSuspendue
  ? 'RÈGLE ABSOLUE — PRISE DE COMMANDE SUSPENDUE : n\'enregistre AUCUNE commande,'
    + ' quelle que soit l\'insistance du client. Continue de repondre, de renseigner et'
    + ' de conseiller normalement. Si le client veut commander, invite-le a contacter'
    + ' directement la boutique, qui prendra le relais. N\'evoque jamais d\'abonnement,'
    + ' de plafond ni de quota.'
  : '';

// Une carte vide n'est pas une panne : le marchand vient d'ouvrir, ou n'a rien
// mis en avant aujourd'hui. Le dire franchement vaut mieux que le silence, et
// bien mieux qu'un article invente.
//
// Le vocabulaire reste neutre : ce texte part au modele tel quel, et la
// boutique n'est pas toujours un restaurant.
const carte_text = lignes.length
  ? lignes.join('\n')
    + '\n\nRÈGLE ABSOLUE : un article marqué « ⛔ ÉPUISÉ » ne doit JAMAIS être commandé ni validé.'
    + ' Si le client en demande un, excuse-toi et propose une alternative disponible.'
  : "AUCUN ARTICLE DISPONIBLE AUJOURD'HUI.\n"
    + 'La boutique n\'a pas encore publié ce qu\'elle propose. Dis-le simplement au client,'
    + ' excuse-toi, et invite-le a repasser plus tard. N\'invente AUCUN article ni AUCUN prix,'
    + ' et ne prends aucune commande tant que rien n\'est publié.';

// Le prompt n'injecte que `menu_text` : la suspension s'y prefixe, en tete,
// parce qu'une regle absolue doit se lire avant la carte qu'elle annule.
const menu_text = prise_commande_text
  ? prise_commande_text + '\n\n' + carte_text
  : carte_text;

// ---- COMMENT LE CLIENT RECUPERE SA COMMANDE.
//
// UNE CONSIGNE AU MODELE N'EST PAS UN VERROU, et ce depot l'a paye plusieurs
// fois. Ce texte sert a PROPOSER le retrait ; c'est /api/commandes/sync qui
// REFUSE un mode que la boutique n'offre pas, qui exige ou non l'adresse, et
// qui date l'heure. Si le modele l'ignore, le serveur le rattrape.
//
// La lecture tolere l'echec : le noeud est en `continueRegularOutput` et peut
// donc transmettre autre chose qu'une fiche. Toute absence retombe sur la
// LIVRAISON, le cote strict -- c'est le comportement de toutes les boutiques en
// service, et une boutique qui livre ne doit jamais cesser d'alerter ses
// livreurs pour une lecture ratee.
let fiche = null;
try { fiche = ($('Lire recuperation').first().json || {}).fiche || null; } catch (e) { fiche = null; }

const mode = String((fiche && fiche.mode_recuperation) || 'livraison');
const preparation = fiche && typeof fiche.delai_preparation_min === 'number'
  ? fiche.delai_preparation_min : null;
const offerteDes = fiche && typeof fiche.livraison_offerte_des === 'number'
  ? fiche.livraison_offerte_des : null;

const attente = preparation
  ? ' Compte environ ' + preparation + ' minutes de preparation : ne promets pas plus tot.'
  : '';

// La gratuite ne concerne que qui livre. NULL veut dire « le livreur annonce
// ses frais » : on ne dit alors rien, plutot que d'annoncer un montant qu'on ne
// connait pas. Zero est un vrai seuil, pas un trou.
let gratuite = '';
if (mode !== 'retrait') {
  if (offerteDes === 0) {
    gratuite = '\nLA LIVRAISON EST OFFERTE chez ce commercant : dis-le au client, il ne'
      + ' reglera rien au livreur.';
  } else if (offerteDes !== null && offerteDes > 0) {
    gratuite = '\nLA LIVRAISON EST OFFERTE a partir de ' + offerteDes + ' FCFA. En dessous,'
      + ' le livreur annonce ses frais a la reception. Tu peux le dire pour aider le client'
      + ' a completer son panier, sans jamais insister.';
  }
}

// UNE BOUTIQUE QUI NE FAIT QUE LIVRER NE LIT RIEN DE PLUS QU'AVANT : son
// assistante doit se comporter exactement comme hier.
let recuperation_text = '';
if (mode === 'retrait') {
  recuperation_text = 'COMMENT LE CLIENT RECUPERE SA COMMANDE\n'
    + 'CETTE BOUTIQUE NE LIVRE PAS : le client vient chercher sa commande sur place.\n'
    + '- NE DEMANDE JAMAIS D\'ADRESSE, et n\'en invente aucune. Elle ne sert a rien ici.\n'
    + '- A l\'etape 2, demande seulement le NOM et le TELEPHONE.\n'
    + '- Demande ensuite a quelle heure il veut retirer sa commande, et accepte'
    + ' « des que c\'est pret » comme reponse.' + attente + '\n'
    + '- Enregistre mode_recuperation = retrait, et heure_retrait au format HH:MM'
    + ' (vide si le client n\'a pas d\'heure precise).\n'
    + '- Ne parle ni de livreur ni de livraison, et n\'annonce aucun frais.';
} else if (mode === 'les_deux') {
  recuperation_text = 'COMMENT LE CLIENT RECUPERE SA COMMANDE\n'
    + 'CE COMMERCANT FAIT LES DEUX : livraison, ou retrait sur place.\n'
    + '- Une fois les articles choisis, demande-lui ce qu\'il prefere. UNE question.\n'
    + '- S\'il choisit la LIVRAISON : nom, telephone et adresse comme d\'habitude, et'
    + ' enregistre mode_recuperation = livraison.\n'
    + '- S\'il choisit le RETRAIT : nom et telephone SEULEMENT, jamais d\'adresse.'
    + ' Demande ensuite son heure de retrait, « des que c\'est pret » etant une reponse'
    + ' valable.' + attente + ' Enregistre mode_recuperation = retrait et heure_retrait au'
    + ' format HH:MM.' + gratuite;
} else if (gratuite) {
  recuperation_text = 'CE QUE LE CLIENT PEUT SAVOIR SUR LA LIVRAISON' + gratuite;
}

const canal = String(data.canal || 'telegram');
const destinataire = String(data.destinataire || '');
const messageText = String(data.texte || 'Message non textuel');
const firstName = String(data.prenom || 'Client');

return [{
  json: {
    sessionId: canal + '_' + destinataire,
    canal: canal,
    chat_id: destinataire,
    first_name: firstName,
    raw_message: messageText,
    menu_text: menu_text,
    prise_commande_text: prise_commande_text,
    recuperation_text: recuperation_text,
    timestamp: Date.now()
  }
}];

