// LE TRI VIT DESORMAIS DANS L APPLICATION.
//
// Ce noeud portait toute la regle : fenetre de douze heures, un seul client
// par chat_id, exclusion des commandes deja dispatchees, tri par horodatage.
// Elle lisait des LIGNES DE FEUILLE, et n existait que parce que la feuille
// rendait tout ce qui correspondait au filtre.
//
// /api/internal/commandes/en-cours applique les memes regles, en SQL, et ne
// rend qu une commande — ou aucune. La regle est desormais lisible, testable,
// et partagee avec le reste du produit au lieu de vivre dans un seul noeud.
//
// Il ne reste ici qu a traduire « rien trouve » en « pas de suite » : sans
// item, n8n saute proprement les noeuds suivants.
const r = $input.first().json || {};

if (r.trouve !== true || !r.order_id) return [];

return [{ json: r }];

