parameters.jsCode:
// Le plafond n'est fiable que si /api/internal/quota a repondu.
//
// « Quota commandes » avale ses echecs, et c'est voulu : une panne du compteur
// ne doit pas fermer la boutique d'un marchand a jour. Mais elle ne doit pas
// non plus l'ouvrir en silence. Sans ce controle, `autorise` vaut undefined,
// `plafondAtteint` vaut faux, et le marchand depasse son forfait sans que
// personne ne l'apprenne — la panne du compteur devient une remise.
//
// On leve APRES l'enregistrement : la commande est ecrite, le client relance.
// L'echec ne lui coute rien, il ne sert qu'a declencher l'alerte technique.
let quota = null;
try { quota = $('Quota commandes').first().json; } catch (e) { quota = null; }

// Une reponse saine porte un booleen. Tout le reste est un « on ne sait pas ».
if (quota && typeof quota.autorise === 'boolean') return [];

// Le message d'erreur n8n est tronque des le premier deux-points ou retour a
// la ligne : l'alerte technique n'y lirait que « Unknown error ». On aplatit.
const brut = quota && quota.error ? String(quota.error) : 'reponse sans champ autorise';
const cause = brut.replace(/[\r\n:]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 160);

return [{ json: { cause } }];

// La derniere commande de ce client, et elle seule.
//
// POURQUOI CE MIROIR EXISTE. L'assistante ecrit dans la feuille ; Supabase n'en
// recevait copie qu'au moment de la demande de confirmation. Un client qui
// CORRIGE ensuite son numero, son nom ou son adresse voyait la feuille mise a
// jour et la base garder l'ancienne valeur — le marchand rappelait alors un
// numero qui n'existe pas. Constate le 19 aout 2026 sur RMO-19082026.
//
// On ne devine pas ce que le client a modifie : on remonte la ligne courante a
// chaque tour. L'ecriture est idempotente, la redondance est le prix de la
// certitude.
const lignes = $input.all().map(i => i.json).filter(l => l && l.order_id);
if (!lignes.length) return [];

// Le plus recent horodatage, a defaut la derniere ligne du tableau.
const avecDate = lignes.filter(l => Date.parse(String(l.timestamp || '')));
const choisie = avecDate.length
  ? avecDate.sort((a, b) => Date.parse(String(a.timestamp)) - Date.parse(String(b.timestamp))).pop()
  : lignes[lignes.length - 1];

// Une commande deja livree ou annulee n'a plus rien a recevoir de la feuille :
// la remonter ecraserait un cycle de vie tenu par l'application.
const statut = String(choisie.status || '').trim().toLowerCase();
if (statut === 'livree' || statut === 'annulee') return [];

return [{ json: choisie }];

// UNE COMMANDE NE SE VALIDE PAS SUR « BONJOUR ».
//
// CE QUI S'EST PASSE. Le 20 aout 2026, un client de Rose Monde a ecrit
// « bonjour ». L'assistante lui a propose de reprendre sa derniere commande —
// et a mis \`commande_validee\` a vrai DANS LE MEME TOUR. Une commande de
// 15 000 F est nee, le marchand a ete alerte, et le client n'avait rien
// demande. Un pas de plus et les livreurs partaient.
//
// POURQUOI UN VERROU ET PAS UNE CONSIGNE. Le prompt disait deja, noir sur
// blanc, que ce champ ne vaut vrai qu'apres un accord explicite, et qu'une
// erreur « ferait partir une course pour rien ». Le modele est passe outre.
// Mistral avait deja ignore une « REGLE ABSOLUE » ailleurs. Une consigne
// n'est pas un verrou.
//
// CE QUE CE VERROU FAIT, ET CE QU'IL NE FAIT PAS. Il pose une condition
// NECESSAIRE, pas suffisante : on ne valide jamais une commande sur un
// message qui n'est qu'une salutation. C'est etroit a dessein — un client
// dit « oui », « ok », « c'est bon », « vas-y » pour confirmer, et aucun de
// ces mots n'est bloque ici. Seul « bonjour » et ses cousins le sont, et
// personne n'a jamais valide un achat en disant bonjour.
//
// Le message du client part normalement : on ne lui repond PAS un refus, on
// retire seulement le drapeau qui aurait alerte le marchand et lance une
// course.

const ai = $('AI Agent').first().json;
const entree = $('When Executed by Another Workflow').first().json;

const aplatir = (t) => String(t ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, ' ')
  .trim();

const message = aplatir(entree.texte || entree.raw_message || entree.message);

// Salutations et formules d'ouverture, seules ou accompagnees du nom de la
// boutique. Rien d'autre : surtout pas « ok », « oui », « d accord », qui sont
// de VRAIS accords.
const SALUTATIONS = [
  'bonjour', 'bonsoir', 'bonne nuit', 'salut', 'coucou', 'hello', 'hi', 'hey',
  'bjr', 'bsr', 'slt', 'cc', 'allo', 'bonne journee', 'bonne soiree',
  'ca va', 'comment ca va', 'comment allez vous', 'vous allez bien',
];

// Le message n'est-il QUE des salutations ? On retire les mots de politesse et
// on regarde s'il reste quelque chose de substantiel.
let reste = message;
for (const s of SALUTATIONS) reste = reste.split(s).join(' ');
reste = reste.replace(/\b(svp|stp|merci|s il vous plait|madame|monsieur|mme|mr)\b/g, ' ').replace(/\s+/g, ' ').trim();

const seulementSalutation = message.length > 0 && SALUTATIONS.some(s => message.includes(s)) && reste.length === 0;

const sortie = JSON.parse(JSON.stringify(ai));
let consentement = 'non applicable';

if (sortie.output && sortie.output.commande_validee === true) {
  if (seulementSalutation) {
    sortie.output.commande_validee = false;
    consentement = 'refuse salutation';
    console.log('Garde consentement — validation retiree, le client n a dit que « ' + message + ' »');
  } else {
    consentement = 'accepte';
  }
}

return [{ json: { ...sortie, consentement, message_client_aplati: message } }];

// LE REFUS DE VENDRE CE QU'ON N'A PLUS — ici, et pas dans le prompt.
//
// « Garde stock », en amont, cherche un nom d'article epuise DANS LE TEXTE de
// l'assistante. C'est une heuristique : elle rate « je vous confirme les deux »
// et ne sait rien des QUANTITES. Un client pouvait commander 5 ensembles quand
// il en restait 2.
//
// Ici, la commande est ecrite : on connait les articles et les quantites. C'est
// le dernier endroit avant que la commande ne parte en confirmation.
//
// ON PENCHE VOLONTAIREMENT DU COTE DU OUI. Refuser une commande bien reelle
// coute un client ; laisser passer une commande de trop coute un appel du
// marchand, ce qu'il fait deja aujourd'hui. Donc : on ne refuse QUE si l'on a
// reconnu l'article ET que le stock est connu ET qu'il est insuffisant. Le
// moindre doute passe.

const ligne = $input.first().json;
const prenom = String($('When Executed by Another Workflow').first().json.prenom || '').trim();

let stocks = [];
try { stocks = $('Lire stocks').first().json.stock || []; } catch (e) { stocks = []; }

const cle = (t) => String(t ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/\s+/g, ' ')
  .trim();

const parNom = {};
for (const s of stocks) parNom[cle(s.nom)] = s;

// `items` est du JSON ecrit par l'assistante. Illisible = on ne sait rien, donc
// on laisse passer : c'est le sens du penchant decrit plus haut.
let articles = [];
try {
  const brut = ligne.items;
  articles = typeof brut === 'string' ? JSON.parse(brut) : (Array.isArray(brut) ? brut : []);
} catch (e) {
  articles = [];
}

const manquants = [];
for (const a of Array.isArray(articles) ? articles : []) {
  if (!a) continue;
  const nom = a.nom || a.plat || a.produit || a.nom_produit;
  const quantite = Math.max(1, Number(a.quantite ?? a['quantité'] ?? a.qte ?? 1) || 1);
  const s = parNom[cle(nom)];

  if (!s) continue;                                   // article inconnu : on ne juge pas
  if (s.disponible === false) { manquants.push(`${nom} n'est plus disponible`); continue; }
  if (s.stock === null || s.stock === undefined) continue;  // le marchand ne compte pas ce produit

  const reste = Number(s.stock);
  if (!Number.isFinite(reste)) continue;
  if (reste >= quantite) continue;

  manquants.push(reste <= 0 ? `${nom} est epuise` : `${nom} — il n'en reste que ${reste}`);
}

const appel = prenom ? ` ${prenom}` : '';
const stock_suffisant = manquants.length ? 'non' : 'oui';
const message_refus = manquants.length
  ? `😔 Desole${appel}, je ne peux pas valider votre commande : ${manquants.join('. ')}.`
    + ` Dites-moi ce que vous souhaitez a la place, je m'en occupe tout de suite !`
  : '';

return [{ json: { ...ligne, stock_suffisant, message_refus, manquants: manquants.join(', ') } }];

// Les infos de la boutique arrivent directement dans le trigger.
const data = $('When Executed by Another Workflow').first().json;

return [{
  json: {
    boutiqueId: String(data.boutique_id || ''),
    whatsapp_marchand: String(data.whatsapp_marchand || ''),
    nom_boutique: String(data.nom_boutique || ''),
  }
}];

const data = $('When Executed by Another Workflow').first().json;
const menuRows = $('Lire Menu').all().map(i => i.json);

// Stocks en temps reel depuis Supabase (le dashboard est la source de verite)
let stocks = [];
try {
  stocks = $('Lire stocks').first().json.stock || [];
} catch (e) { stocks = []; }

const parNom = {};
for (const s of stocks) {
  parNom[String(s.nom || '').trim().toLowerCase()] = s;
}

// Selection du jour, avec marquage EPUISE en direct.
const lignes = [];
for (const r of menuRows) {
  // Lire Menu emet un item vide quand l'onglet du marchand n'a aucune ligne.
  if (!r || !r.nom) continue;
  // Le catalogue vient desormais de l application, qui rend `duJour` en
  // booleen ; la feuille rendait `menu_du_jour` en texte. On accepte les deux
  // le temps que plus rien ne vienne de la feuille.
  const duJour = r.duJour === true || String(r.menu_du_jour || '').toUpperCase() === 'TRUE';
  if (!duJour) continue;

  // « Lire stocks » reste l autorite ; a defaut, le catalogue porte lui-meme le
  // stock. NULL veut dire « le marchand ne compte pas ce produit », jamais zero.
  const s = parNom[String(r.nom || '').trim().toLowerCase()];
  const dispo = s ? s.disponible : r.disponible;
  const reste = s ? s.stock : (r.stock === undefined ? null : r.stock);
  const epuise = dispo === false || (reste !== null && reste !== undefined && reste <= 0);
  lignes.push(`- ${r.nom} : ${r.prix} FCFA${epuise ? ' — ⛔ ÉPUISÉ' : ''}`);
}

// « MENU DU JOUR » EST UN CONCEPT DE RESTAURANT.
//
// Une boutique de vetements, une pharmacie ou un quincaillier n ont pas de
// selection quotidienne : ils ont un catalogue. Filtrer sur `duJour` leur
// rendait une carte VIDE, et l assistante annoncait « rien publie aujourd hui »
// alors que les articles etaient bel et bien en ligne sur la vitrine.
//
// Regle : si le marchand n a rien mis en avant, on presente tout ce qui est
// disponible. Celui qui compose une selection la voit respectee ; celui qui
// n en compose pas vend quand meme.
if (lignes.length === 0) {
  for (const r of menuRows) {
    if (!r || !r.nom) continue;
    const s = parNom[String(r.nom || '').trim().toLowerCase()];
    const dispo = s ? s.disponible : r.disponible;
    const reste = s ? s.stock : (r.stock === undefined ? null : r.stock);
    if (dispo === false) continue;
    const epuise = reste !== null && reste !== undefined && reste <= 0;
    lignes.push(`- ${r.nom} : ${r.prix} FCFA${epuise ? ' — ⛔ ÉPUISÉ' : ''}`);
  }
}

// Plafond de commandes du marchand. Le compteur vit dans l'application ; ici
// on ne fait qu'en tirer une consigne pour l'assistante.
//
// Toute lecture douteuse laisse passer : le noeud tolere l'erreur et peut donc
// transmettre autre chose qu'une reponse. On ne bloque que sur un `autorise`
// explicitement faux, jamais sur une absence.
let quota = null;
try { quota = $('Quota commandes').first().json; } catch (e) { quota = null; }
const priseSuspendue = !!quota && quota.autorise === false;

// Le client n'a pas a savoir que son commercant a atteint un plafond : ce
// n'est ni son probleme ni son affaire. On lui donne une porte de sortie
// utile, pas une explication commerciale.
const prise_commande_text = priseSuspendue
  ? 'RÈGLE ABSOLUE — PRISE DE COMMANDE SUSPENDUE : n\'enregistre AUCUNE commande,'
    + ' quelle que soit l\'insistance du client. Continue de repondre, de renseigner et'
    + ' de conseiller normalement. Si le client veut commander, invite-le a contacter'
    + ' directement la boutique, qui prendra le relais. N\'evoque jamais d\'abonnement,'
    + ' de plafond ni de quota.'
  : '';

// Une carte vide n'est pas une panne : le marchand vient d'ouvrir, ou n'a rien
// mis en avant aujourd'hui. Le dire franchement vaut mieux que le silence, et
// bien mieux qu'un article invente.
//
// Le vocabulaire reste neutre : ce texte part au modele tel quel, et la
// boutique n'est pas toujours un restaurant.
const carte_text = lignes.length
  ? lignes.join('\n')
    + '\n\nRÈGLE ABSOLUE : un article marqué « ⛔ ÉPUISÉ » ne doit JAMAIS être commandé ni validé.'
    + ' Si le client en demande un, excuse-toi et propose une alternative disponible.'
  : "AUCUN ARTICLE DISPONIBLE AUJOURD'HUI.\n"
    + 'La boutique n\'a pas encore publié ce qu\'elle propose. Dis-le simplement au client,'
    + ' excuse-toi, et invite-le a repasser plus tard. N\'invente AUCUN article ni AUCUN prix,'
    + ' et ne prends aucune commande tant que rien n\'est publié.';

// Le prompt n'injecte que `menu_text` : la suspension s'y prefixe, en tete,
// parce qu'une regle absolue doit se lire avant la carte qu'elle annule.
const menu_text = prise_commande_text
  ? prise_commande_text + '\n\n' + carte_text
  : carte_text;

// ---- COMMENT LE CLIENT RECUPERE SA COMMANDE.
//
// UNE CONSIGNE AU MODELE N'EST PAS UN VERROU, et ce depot l'a paye plusieurs
// fois. Ce texte sert a PROPOSER le retrait ; c'est /api/commandes/sync qui
// REFUSE un mode que la boutique n'offre pas, qui exige ou non l'adresse, et
// qui date l'heure. Si le modele l'ignore, le serveur le rattrape.
//
// La lecture tolere l'echec : le noeud est en `continueRegularOutput` et peut
// donc transmettre autre chose qu'une fiche. Toute absence retombe sur la
// LIVRAISON, le cote strict -- c'est le comportement de toutes les boutiques en
// service, et une boutique qui livre ne doit jamais cesser d'alerter ses
// livreurs pour une lecture ratee.
let fiche = null;
try { fiche = ($('Lire recuperation').first().json || {}).fiche || null; } catch (e) { fiche = null; }

const mode = String((fiche && fiche.mode_recuperation) || 'livraison');
const preparation = fiche && typeof fiche.delai_preparation_min === 'number'
  ? fiche.delai_preparation_min : null;
const offerteDes = fiche && typeof fiche.livraison_offerte_des === 'number'
  ? fiche.livraison_offerte_des : null;

const attente = preparation
  ? ' Compte environ ' + preparation + ' minutes de preparation : ne promets pas plus tot.'
  : '';

// La gratuite ne concerne que qui livre. NULL veut dire « le livreur annonce
// ses frais » : on ne dit alors rien, plutot que d'annoncer un montant qu'on ne
// connait pas. Zero est un vrai seuil, pas un trou.
let gratuite = '';
if (mode !== 'retrait') {
  if (offerteDes === 0) {
    gratuite = '\nLA LIVRAISON EST OFFERTE chez ce commercant : dis-le au client, il ne'
      + ' reglera rien au livreur.';
  } else if (offerteDes !== null && offerteDes > 0) {
    gratuite = '\nLA LIVRAISON EST OFFERTE a partir de ' + offerteDes + ' FCFA. En dessous,'
      + ' le livreur annonce ses frais a la reception. Tu peux le dire pour aider le client'
      + ' a completer son panier, sans jamais insister.';
  }
}

// UNE BOUTIQUE QUI NE FAIT QUE LIVRER NE LIT RIEN DE PLUS QU'AVANT : son
// assistante doit se comporter exactement comme hier.
let recuperation_text = '';
if (mode === 'retrait') {
  recuperation_text = 'COMMENT LE CLIENT RECUPERE SA COMMANDE\n'
    + 'CETTE BOUTIQUE NE LIVRE PAS : le client vient chercher sa commande sur place.\n'
    + '- NE DEMANDE JAMAIS D\'ADRESSE, et n\'en invente aucune. Elle ne sert a rien ici.\n'
    + '- A l\'etape 2, demande seulement le NOM et le TELEPHONE.\n'
    + '- Demande ensuite a quelle heure il veut retirer sa commande, et accepte'
    + ' « des que c\'est pret » comme reponse.' + attente + '\n'
    + '- Enregistre mode_recuperation = retrait, et heure_retrait au format HH:MM'
    + ' (vide si le client n\'a pas d\'heure precise).\n'
    + '- Ne parle ni de livreur ni de livraison, et n\'annonce aucun frais.';
} else if (mode === 'les_deux') {
  recuperation_text = 'COMMENT LE CLIENT RECUPERE SA COMMANDE\n'
    + 'CE COMMERCANT FAIT LES DEUX : livraison, ou retrait sur place.\n'
    + '- Une fois les articles choisis, demande-lui ce qu\'il prefere. UNE question.\n'
    + '- S\'il choisit la LIVRAISON : nom, telephone et adresse comme d\'habitude, et'
    + ' enregistre mode_recuperation = livraison.\n'
    + '- S\'il choisit le RETRAIT : nom et telephone SEULEMENT, jamais d\'adresse.'
    + ' Demande ensuite son heure de retrait, « des que c\'est pret » etant une reponse'
    + ' valable.' + attente + ' Enregistre mode_recuperation = retrait et heure_retrait au'
    + ' format HH:MM.' + gratuite;
} else if (gratuite) {
  recuperation_text = 'CE QUE LE CLIENT PEUT SAVOIR SUR LA LIVRAISON' + gratuite;
}

const canal = String(data.canal || 'telegram');
const destinataire = String(data.destinataire || '');
const messageText = String(data.texte || 'Message non textuel');
const firstName = String(data.prenom || 'Client');

return [{
  json: {
    sessionId: canal + '_' + destinataire,
    canal: canal,
    chat_id: destinataire,
    first_name: firstName,
    raw_message: messageText,
    menu_text: menu_text,
    prise_commande_text: prise_commande_text,
    recuperation_text: recuperation_text,
    timestamp: Date.now()
  }
}];

