const ai = $('AI Agent').first().json;
const texte = String((ai.output && ai.output.reponse) || ai.reponse || '').toLowerCase();
const prenom = String($('When Executed by Another Workflow').first().json.prenom || '').trim();

// Plafond de commandes. La consigne envoyee au modele lui demande de ne rien
// enregistrer, mais une consigne n'est pas un verrou : si le modele passe
// outre, la commande s'ecrit quand meme et le marchand depasse son forfait.
// Ici, le refus ne se discute plus — c'est la branche qui l'impose.
let quota = null;
try { quota = $('Quota commandes').first().json; } catch (e) { quota = null; }
const plafondAtteint = !!quota && quota.autorise === false;

let stocks = [];
try { stocks = $('Lire stocks').first().json.stock || []; } catch (e) { stocks = []; }

const epuises = stocks.filter(s => s.disponible === false || (s.stock !== null && s.stock <= 0));
const hits = epuises.filter(s => texte.includes(String(s.nom || '').trim().toLowerCase()));

// Le plafond prime sur la rupture : inutile d'annoncer un article epuise a
// quelqu'un dont la commande ne sera de toute facon pas prise.
const appel = prenom ? ` ${prenom}` : '';
let garde_stock = 'ok';
let message_refus = '';

if (plafondAtteint) {
  garde_stock = 'bloque';
  // Le texte vient de l'application quand elle en fournit un : c'est la que
  // vit la formulation, et elle ne doit exister qu'a un seul endroit. Le
  // client n'a pas a apprendre que son commercant a atteint un plafond.
  const dit = String(quota.messageClient || '').trim()
    || 'Je ne peux pas enregistrer votre commande pour le moment.'
       + ' Appelez directement la boutique, elle prendra le relais.';
  message_refus = `😞 Désolé${appel} — ${dit}`;
} else if (hits.length > 0) {
  garde_stock = 'bloque';
  message_refus = `😔 Désolé${appel}, forte demande : ${hits.map(h => h.nom).join(', ')}`
    + ` vient de partir en rupture. Votre commande n'est PAS validée.`
    + ` Je vous propose autre chose ! 🙏`;
}

return [{ json: { ...ai, garde_stock, message_refus, plats_epuises: hits.map(h => h.nom).join(', ') } }];

