parameters.jsCode:
// Le plafond n'est fiable que si /api/internal/quota a repondu.
//
// « Quota commandes » avale ses echecs, et c'est voulu : une panne du compteur
// ne doit pas fermer la boutique d'un marchand a jour. Mais elle ne doit pas
// non plus l'ouvrir en silence. Sans ce controle, `autorise` vaut undefined,
// `plafondAtteint` vaut faux, et le marchand depasse son forfait sans que
// personne ne l'apprenne — la panne du compteur devient une remise.
//
// On leve APRES l'enregistrement : la commande est ecrite, le client relance.
// L'echec ne lui coute rien, il ne sert qu'a declencher l'alerte technique.
let quota = null;
try { quota = $('Quota commandes').first().json; } catch (e) { quota = null; }

// Une reponse saine porte un booleen. Tout le reste est un « on ne sait pas ».
if (quota && typeof quota.autorise === 'boolean') return [];

// Le message d'erreur n8n est tronque des le premier deux-points ou retour a
// la ligne : l'alerte technique n'y lirait que « Unknown error ». On aplatit.
const brut = quota && quota.error ? String(quota.error) : 'reponse sans champ autorise';
const cause = brut.replace(/[\r\n:]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 160);

return [{ json: { cause } }];

// La derniere commande de ce client, et elle seule.
//
// POURQUOI CE MIROIR EXISTE. L'assistante ecrit dans la feuille ; Supabase n'en
// recevait copie qu'au moment de la demande de confirmation. Un client qui
// CORRIGE ensuite son numero, son nom ou son adresse voyait la feuille mise a
// jour et la base garder l'ancienne valeur — le marchand rappelait alors un
// numero qui n'existe pas. Constate le 19 aout 2026 sur RMO-19082026.
//
// On ne devine pas ce que le client a modifie : on remonte la ligne courante a
// chaque tour. L'ecriture est idempotente, la redondance est le prix de la
// certitude.
const lignes = $input.all().map(i => i.json).filter(l => l && l.order_id);
if (!lignes.length) return [];

// Le plus recent horodatage, a defaut la derniere ligne du tableau.
const avecDate = lignes.filter(l => Date.parse(String(l.timestamp || '')));
const choisie = avecDate.length
  ? avecDate.sort((a, b) => Date.parse(String(a.timestamp)) - Date.parse(String(b.timestamp))).pop()
  : lignes[lignes.length - 1];

// Une commande deja livree ou annulee n'a plus rien a recevoir de la feuille :
// la remonter ecraserait un cycle de vie tenu par l'application.
const statut = String(choisie.status || '').trim().toLowerCase();
if (statut === 'livree' || statut === 'annulee') return [];

return [{ json: choisie }];

// UNE COMMANDE NE SE VALIDE PAS SUR « BONJOUR ».
//
// CE QUI S'EST PASSE. Le 20 aout 2026, un client de Rose Monde a ecrit
// « bonjour ». L'assistante lui a propose de reprendre sa derniere commande —
// et a mis \`commande_validee\` a vrai DANS LE MEME TOUR. Une commande de
// 15 000 F est nee, le marchand a ete alerte, et le client n'avait rien
// demande. Un pas de plus et les livreurs partaient.
//
// POURQUOI UN VERROU ET PAS UNE CONSIGNE. Le prompt disait deja, noir sur
// blanc, que ce champ ne vaut vrai qu'apres un accord explicite, et qu'une
// erreur « ferait partir une course pour rien ». Le modele est passe outre.
// Mistral avait deja ignore une « REGLE ABSOLUE » ailleurs. Une consigne
// n'est pas un verrou.
//
// CE QUE CE VERROU FAIT, ET CE QU'IL NE FAIT PAS. Il pose une condition
// NECESSAIRE, pas suffisante : on ne valide jamais une commande sur un
// message qui n'est qu'une salutation. C'est etroit a dessein — un client
// dit « oui », « ok », « c'est bon », « vas-y » pour confirmer, et aucun de
// ces mots n'est bloque ici. Seul « bonjour » et ses cousins le sont, et
// personne n'a jamais valide un achat en disant bonjour.
//
// Le message du client part normalement : on ne lui repond PAS un refus, on
// retire seulement le drapeau qui aurait alerte le marchand et lance une
// course.

const ai = $('AI Agent').first().json;
const entree = $('When Executed by Another Workflow').first().json;

const aplatir = (t) => String(t ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, ' ')
  .trim();

const message = aplatir(entree.texte || entree.raw_message || entree.message);

// Salutations et formules d'ouverture, seules ou accompagnees du nom de la
// boutique. Rien d'autre : surtout pas « ok », « oui », « d accord », qui sont
// de VRAIS accords.
const SALUTATIONS = [
  'bonjour', 'bonsoir', 'bonne nuit', 'salut', 'coucou', 'hello', 'hi', 'hey',
  'bjr', 'bsr', 'slt', 'cc', 'allo', 'bonne journee', 'bonne soiree',
  'ca va', 'comment ca va', 'comment allez vous', 'vous allez bien',
];

// Le message n'est-il QUE des salutations ? On retire les mots de politesse et
// on regarde s'il reste quelque chose de substantiel.
let reste = message;
for (const s of SALUTATIONS) reste = reste.split(s).join(' ');
reste = reste.replace(/\b(svp|stp|merci|s il vous plait|madame|monsieur|mme|mr)\b/g, ' ').replace(/\s+/g, ' ').trim();

const seulementSalutation = message.length > 0 && SALUTATIONS.some(s => message.includes(s)) && reste.length === 0;

const sortie = JSON.parse(JSON.stringify(ai));
let consentement = 'non applicable';

if (sortie.output && sortie.output.commande_validee === true) {
  if (seulementSalutation) {
    sortie.output.commande_validee = false;
    consentement = 'refuse salutation';
    console.log('Garde consentement — validation retiree, le client n a dit que « ' + message + ' »');
  } else {
    consentement = 'accepte';
  }
}

return [{ json: { ...sortie, consentement, message_client_aplati: message } }];

// LE REFUS DE VENDRE CE QU'ON N'A PLUS — ici, et pas dans le prompt.
//
// « Garde stock », en amont, cherche un nom d'article epuise DANS LE TEXTE de
// l'assistante. C'est une heuristique : elle rate « je vous confirme les deux »
// et ne sait rien des QUANTITES. Un client pouvait commander 5 ensembles quand
// il en restait 2.
//
// Ici, la commande est ecrite : on connait les articles et les quantites. C'est
// le dernier endroit avant que la commande ne parte en confirmation.
//
// ON PENCHE VOLONTAIREMENT DU COTE DU OUI. Refuser une commande bien reelle
// coute un client ; laisser passer une commande de trop coute un appel du
// marchand, ce qu'il fait deja aujourd'hui. Donc : on ne refuse QUE si l'on a
// reconnu l'article ET que le stock est connu ET qu'il est insuffisant. Le
// moindre doute passe.

const ligne = $input.first().json;
const prenom = String($('When Executed by Another Workflow').first().json.prenom || '').trim();

let stocks = [];
try { stocks = $('Lire stocks').first().json.stock || []; } catch (e) { stocks = []; }

const cle = (t) => String(t ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/\s+/g, ' ')
  .trim();

const parNom = {};
for (const s of stocks) parNom[cle(s.nom)] = s;

// `items` est du JSON ecrit par l'assistante. Illisible = on ne sait rien, donc
// on laisse passer : c'est le sens du penchant decrit plus haut.
let articles = [];
try {
  const brut = ligne.items;
  articles = typeof brut === 'string' ? JSON.parse(brut) : (Array.isArray(brut) ? brut : []);
} catch (e) {
  articles = [];
}

const manquants = [];
for (const a of Array.isArray(articles) ? articles : []) {
  if (!a) continue;
  const nom = a.nom || a.plat || a.produit || a.nom_produit;
  const quantite = Math.max(1, Number(a.quantite ?? a['quantité'] ?? a.qte ?? 1) || 1);
  const s = parNom[cle(nom)];

  if (!s) continue;                                   // article inconnu : on ne juge pas
  if (s.disponible === false) { manquants.push(`${nom} n'est plus disponible`); continue; }
  if (s.stock === null || s.stock === undefined) continue;  // le marchand ne compte pas ce produit

  const reste = Number(s.stock);
  if (!Number.isFinite(reste)) continue;
  if (reste >= quantite) continue;

  manquants.push(reste <= 0 ? `${nom} est epuise` : `${nom} — il n'en reste que ${reste}`);
}

const appel = prenom ? ` ${prenom}` : '';
const stock_suffisant = manquants.length ? 'non' : 'oui';
const message_refus = manquants.length
  ? `😔 Desole${appel}, je ne peux pas valider votre commande : ${manquants.join('. ')}.`
    + ` Dites-moi ce que vous souhaitez a la place, je m'en occupe tout de suite !`
  : '';

return [{ json: { ...ligne, stock_suffisant, message_refus, manquants: manquants.join(', ') } }];
